// Eliminar pedidos fantasma (sin ítems) desde la modal de Caja
async function deleteGhostOrder(orderId) {
  if (!confirm(`¿Eliminar el pedido #${orderId}? No tiene ítems y no se puede cobrar.`)) return;
  try {
    const res = await fetch('/api/orders/update-status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: orderId, status: 'cancelled' })
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    // También intentar marcarlo como cerrado en el servidor
    await fetch('/api/orders/pay', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: orderId, method: 'error-vacios', total: 0, commission: 0, closedAt: Date.now() })
    }).catch(() => {});
    toast(`Pedido #${orderId} eliminado`, 'success');
    await syncAppData();
    openCajaActions(); // refrescar la modal
  } catch (e) {
    toast('Error al eliminar: ' + e.message, 'error');
  }
}